<section class="auth-shell"><aside class="auth-story"><p class="eyebrow">WELCOME TO THE NETWORK</p><h1>A little less waste.<br>A lot more<br><em>possibility.</em></h1><p>Bring your organization, your time, or your curiosity. Start with a secure FoodRescue account.</p><div class="story-symbol" aria-hidden="true">↗</div></aside><div class="auth-card">
<?php $headings = ['login'=>'Welcome back.','register'=>'Let’s make a connection.','forgot-password'=>'Reset your password.','reset-password'=>'A fresh start.','verify-email'=>'Verify your email.']; ?>
<p class="eyebrow">YOUR FOODRESCUE ACCOUNT</p><h2><?= e($headings[$mode]) ?></h2>
<?php if ($mode === 'login'): ?><p>Sign in to your community workspace.</p><?php if (isset($_GET['reset'])): ?><p class="notice">Password updated. Sign in with your new password.</p><?php endif ?><?php elseif ($mode === 'register'): ?><p>Choose how you’d like to contribute.</p><?php elseif ($mode === 'forgot-password'): ?><p>We’ll queue a recovery link if your account is active.</p><?php else: ?><p>Use the link in your account email to continue.</p><?php endif ?>
<form data-api="/api/auth/<?= e($mode) ?>">
<?php if ($mode === 'register'): ?><label for="name">Full name</label><input id="name" name="name" autocomplete="name" required maxlength="120"><label for="role">I’m joining as</label><select id="role" name="role" required><option value="donor">Donor — share surplus food</option><option value="receiver">NGO / Receiver — support a community</option><option value="volunteer">Volunteer — help with collection</option></select><?php endif ?>
<?php if (in_array($mode,['register','login','forgot-password'],true)): ?><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="254"><?php endif ?>
<?php if (in_array($mode,['register','login','reset-password'],true)): ?><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="<?= $mode === 'login' ? 'current-password' : 'new-password' ?>" required <?= $mode === 'login' ? '' : 'minlength="12" maxlength="72"' ?>><?php if ($mode !== 'login'): ?><small>Use 12–72 bytes. A long, unique passphrase works well.</small><?php endif ?><?php endif ?>
<?php if (in_array($mode,['reset-password','verify-email'],true)): ?><input type="hidden" name="token" id="account-token"><?php endif ?>
<p class="form-message" role="alert" tabindex="-1" hidden></p>
<button class="button full" type="submit"><?= e(['login'=>'Sign in →','register'=>'Create account ↗','forgot-password'=>'Send recovery link →','reset-password'=>'Save new password →','verify-email'=>'Verify email →'][$mode]) ?></button>
</form>
<?php if ($mode === 'login'): ?><a class="sub-link" href="/forgot-password">Forgot your password?</a><p class="auth-switch">New to FoodRescue? <a href="/register">Create an account</a></p><?php else: ?><p class="auth-switch">Already have an account? <a href="/login">Sign in</a></p><?php endif ?>
</div></section>
